static int projection(const char *role,const char *id,const char *image,const char *config,const char *network,const char *state,const char *owner,char output[65]){char value[1024];int n=snprintf(value,sizeof(value),"domain=darshan-recovery-docker-observation-projection-v1\nrole=%s\nid=%s\nimage=%s\nconfig=%s\nnetwork=%s\nstate=%s\nowner=%s\n",role,id,image,config,network,state,owner);return n>0&&(size_t)n<sizeof(value)?hash(value,(size_t)n,output):-1;}
